const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2, PIc=Math.PI;
const md=(a,n)=>((a%n)+n)%n;
const ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const dot=style==='dot', ring=style==='ring', halftone=style==='halftone', noir=style==='noir';
const en=clp(P.energy,0,1)*(.5+.7*K.intensity);
const dens=clp(P.density,0,1);
const hue=md(P.hue,360);

// background per style discipline
let bgH,bgS,bgB;
if(dot){ bgH=md(hue+205,360); bgS=24; bgB=88; }        // warm poster paper vs bold dots
else if(ring){ bgH=md(hue+180,360); bgS=30; bgB=14; }  // dark, schematic rings glow
else if(halftone){ bgH=45; bgS=8; bgB=90; }            // newsprint cream
else { bgH=hue; bgS=35; bgB=7; }                        // noir near-black

// ---- cached packing geometry (keyed on size/seed/density bucket) ----
const dB=Math.round(dens*6);
const key=W+'x'+Hh+'|'+P.seed+'|'+dB;
if(S.key!==key){
  S.key=key;
  const N=Math.min(150, Math.round(14+dens*150));
  const pts=[];
  for(let i=0;i<N;i++){ pts.push({x:fr(i*7.3+1)*W, y:fr(i*11.9+2)*Hh, ph:fr(i*3.7+5), tone:fr(i*5.9+9)}); }
  for(let i=0;i<N;i++){
    const a=pts[i]; let r=Math.min(a.x,W-a.x,a.y,Hh-a.y);
    for(let j=0;j<N;j++){ if(j===i)continue; const b=pts[j]; const d=Math.hypot(a.x-b.x,a.y-b.y)*0.5; if(d<r)r=d; }
    a.r=Math.max(u*0.006, r);
  }
  S.pts=pts;
}
const pts=S.pts;

// ---- LIVE COMPOSITE ----
noStroke();
background(bgH,bgS,bgB);

// per-section palette shift (dot-poster rotates through a limited set)
const sec=Math.floor(md(K.section,8));
const offs=[0,34,-30,66,150,200];
const growRate=0.11*P.speed, sc=clp(P.scale,.3,1.8);
const lx=P.x*W, ly=P.y*Hh;
const popAmt=clp(P.pop,0,1);
const bassPop = popAmt*(A.bass*0.8 + K.pulse*0.35);

for(let i=0;i<pts.length;i++){
  const c=pts[i];
  // grow/pop life cycle: L wraps 0..1 (grow then pop). K.t term => never re-phases.
  let L = md(K.beat*growRate + K.t*0.02*P.speed + c.ph, 1);
  if(P.act==='breathe') L = 0.5+0.5*Math.sin((K.beat*growRate+K.t*0.02+c.ph)*TAU);
  let gf = ez(clp(L*1.3,0,1));
  if(P.act==='pop'){ gf *= clp(1.15-L*0.6,0,1.15); } // sharper snap-and-fall
  gf *= (0.9+0.16*K.swell) + bassPop*(0.4+0.6*c.tone);
  const r = c.r*sc*gf;
  if(r<u*0.004) continue;
  const hcol = md(hue + offs[(i+sec)%offs.length] + K.t*1.6, 360);
  const bright = clp((noir?70:88) + 12*Math.sin(K.t*0.4+c.ph*TAU), 0, 100);

  if(ring){
    noFill(); const nr=3;
    for(let k=1;k<=nr;k++){ const rr=r*(k/nr); stroke(hcol, 70, bright, 70); strokeWeight(clp(r*0.05,0.6,3)); circle(c.x,c.y,rr*2); }
    stroke(hcol,40,100,40); strokeWeight(clp(r*0.05,0.6,3)); noFill(); // subtle inner glow ring already drawn
  } else if(halftone){
    // CMYK-ish misregistered stack (print halftone tell)
    const off=r*0.10*(1+0.5*Math.sin(K.t*0.6+i));
    noStroke();
    fill(md(hcol+180,360), 65, 95, 45); circle(c.x-off,c.y+off, r*2);
    fill(md(hcol+40,360), 70, 98, 45); circle(c.x+off,c.y, r*2);
    fill(hcol, 78, 96, 55); circle(c.x,c.y-off*0.7, r*2*0.9);
  } else if(noir){
    // chiaroscuro sphere — form from light only, no outline
    const dx=(lx-c.x), dy=(ly-c.y), dl=Math.hypot(dx,dy)+1;
    const ox=dx/dl*r*0.32, oy=dy/dl*r*0.32;
    noStroke();
    fill(hue, 40, 10, 100); circle(c.x,c.y, r*2);
    fill(hcol, 45, 42, 90); circle(c.x+ox*0.4, c.y+oy*0.4, r*1.5);
    fill(hcol, 30, 92, 90); circle(c.x+ox, c.y+oy, r*0.8);
    fill(hcol, 12, 100, 70); circle(c.x+ox*1.35, c.y+oy*1.35, r*0.34);
  } else {
    // dot poster — bold flat fill + concentric contrast ring
    noStroke(); fill(hcol, 72, bright, 100); circle(c.x,c.y, r*2);
    noFill(); stroke(md(hcol+ (c.tone>0.5?18:-18),360), 78, bright*0.65, 100); strokeWeight(clp(r*0.10,0.8,4)); circle(c.x,c.y, r*1.28);
  }
}

// bass bloom flash — partial additive wash centered on anchor (never full-frame)
if(en>0.02){
  blendMode(ADD);
  const fl=(K.pulse*0.5 + A.bass*0.9)*en;
  noStroke(); fill(md(hue+ (sec*20),360), 55, 100, 10*fl);
  circle(lx, ly, u*(0.4+0.6*fl));
  blendMode(BLEND);
}
drawingContext.shadowBlur=0;

const D = { energy:.62, scale:1, density:.55, speed:1, gamma:2.2, persist:.4, hue:255, x:.5, y:.5, style:'silk', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse density grid (long axis 240; keyed on aspect, survives resize) ----
const LA = 240;
let cw, ch;
if (width >= height){ cw = LA; ch = Math.max(64, Math.round(LA*height/width)); }
else { ch = LA; cw = Math.max(64, Math.round(LA*width/height)); }
if (S.gridKey !== cw+'x'+ch){
  S.gridKey = cw+'x'+ch; S.cw = cw; S.ch = ch;
  S.hist = new Float32Array(cw*ch);
  S.acc = new Float32Array(cw*ch);
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(cw, ch); S.buf.pixelDensity(1);
  S.fc = 0;
}
cw = S.cw; ch = S.ch; const NG = cw*ch;

// ---- seeded Clifford basin (verified-robust chaotic sets; rebuild on seed change) ----
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
  const SETS = [[-1.402,1.836,1.977,1.978],[1.956,1.864,1.699,-1.952],[1.898,1.599,-1.915,1.895],[1.418,1.749,-1.559,-1.869],[1.504,1.633,1.887,-1.982],[-1.346,-1.924,1.611,1.972],[1.663,-1.792,1.993,-1.573],[-1.945,-1.596,-1.709,-1.739],[1.357,1.837,-1.416,-1.728],[1.836,1.659,-1.817,-1.249],[1.873,-1.529,1.845,-1.655],[1.464,-1.935,-1.914,1.181],[-1.877,-1.953,1.953,0.86],[-1.835,-1.881,-1.797,1.504],[-1.948,-1.001,1.988,1.778],[-1.882,-1.421,-1.736,1.887]];
  const bs = SETS[Math.floor(fr(9)*SETS.length) % SETS.length];
  S.ba = bs[0] + (fr(1)*2-1)*0.02;
  S.bb = bs[1] + (fr(2)*2-1)*0.02;
  S.bc = bs[2] + (fr(3)*2-1)*0.02;
  S.bd = bs[3] + (fr(4)*2-1)*0.02;
  S.hoff = fr(5); S.rot0 = fr(6)*6.283; S.secOff = fr(7)*6.283; S.zph = fr(8)*6.283;
  if (S.acc) S.acc.fill(0);
  S.fc = 0;
  S.palKey = null;
}

// ---- palette LUT (256x3), rebuilt on style/hue/seed change ----
if (S.palKey !== P.style+'|'+Math.round(P.hue)+'|'+P.seed){
  S.palKey = P.style+'|'+Math.round(P.hue)+'|'+P.seed;
  const pal = S.pal || (S.pal = new Float32Array(768));
  const st = P.style;
  let stops;
  if (st==='plasma') stops = [[0,0.05,0.02,0.13],[0.34,0.55,0.07,0.52],[0.60,0.92,0.20,0.72],[0.80,0.30,0.74,0.96],[1,0.82,1,1]];
  else if (st==='ember') stops = [[0,0.02,0.006,0.012],[0.26,0.34,0.03,0.01],[0.50,0.82,0.20,0.02],[0.72,1,0.55,0.08],[0.88,1,0.85,0.34],[1,1,0.98,0.86]];
  else if (st==='bio') stops = [[0,0.005,0.06,0.08],[0.30,0.02,0.33,0.30],[0.55,0.06,0.68,0.46],[0.76,0.32,0.96,0.72],[1,0.84,1,0.95]];
  else if (st==='pencil') stops = [[0,0.90,0.88,0.82],[1,0.90,0.88,0.82]];
  else stops = [[0,0.06,0.04,0.17],[0.28,0.25,0.10,0.45],[0.52,0.56,0.20,0.52],[0.72,0.92,0.49,0.32],[0.88,1,0.80,0.44],[1,1,0.96,0.82]];
  // luminance-preserving hue rotation (identity at default hue=255)
  const ang = ((P.hue-255)/360)*6.28318;
  const U = Math.cos(ang), Wv = Math.sin(ang);
  const m00=.299+.701*U+.168*Wv, m01=.587-.587*U+.330*Wv, m02=.114-.114*U-.497*Wv;
  const m10=.299-.299*U-.328*Wv, m11=.587+.413*U+.035*Wv, m12=.114-.114*U+.292*Wv;
  const m20=.299-.300*U+1.250*Wv, m21=.587-.588*U-1.050*Wv, m22=.114+.886*U-.203*Wv;
  const doRot = Math.abs(ang) > 0.001;
  for (let i=0;i<256;i++){ const t=i/255;
    let s0=stops[0], s1=stops[stops.length-1];
    for (let k=0;k<stops.length-1;k++){ if (t>=stops[k][0] && t<=stops[k+1][0]){ s0=stops[k]; s1=stops[k+1]; break; } }
    const seg=(s1[0]-s0[0])||1, f=(t-s0[0])/seg;
    let r=s0[1]+(s1[1]-s0[1])*f, g=s0[2]+(s1[2]-s0[2])*f, b=s0[3]+(s1[3]-s0[3])*f;
    if (doRot){
      const nr=m00*r+m01*g+m02*b, ng=m10*r+m11*g+m12*b, nb=m20*r+m21*g+m22*b;
      r=nr<0?0:(nr>1?1:nr); g=ng<0?0:(ng>1?1:ng); b=nb<0?0:(nb>1?1:nb);
    }
    pal[i*3]=r; pal[i*3+1]=g; pal[i*3+2]=b;
  }
}
const pal = S.pal;

// ---- temporal program: eased section arc + continuous K.t coefficient drift ----
const intn = (K.intensity!=null?K.intensity:0.6);
const sec = (K.section!=null?K.section:0);
if (S.secSm == null || sec < S.secSm - 4) S.secSm = sec;
S.secSm += (sec - S.secSm)*0.02;
const secSm = S.secSm;
const T = K.t*P.speed;
const dAmp = 0.10, ssh = Math.sin(secSm*0.8 + S.secOff);
const a = S.ba + Math.sin(T*0.041)*dAmp*1.2 + Math.sin(T*0.017+1.3)*dAmp*0.5 + ssh*0.07;
const b = S.bb + Math.cos(T*0.037+1.7)*dAmp*1.1 - ssh*0.07;
const c = S.bc + Math.sin(T*0.029+3.1)*dAmp*1.0 + Math.cos(secSm*0.6)*0.08;
const d = S.bd + Math.cos(T*0.047+4.4)*dAmp*1.1 - Math.sin(secSm*0.5)*0.08;

// ---- iterate Clifford map fresh each frame, splat into density grid (canonical orientation) ----
let iters = Math.floor((22000 + P.density*40000)*(0.75+intn*0.4) + A.bass*12000);
if (iters>70000) iters=70000;
const hist = S.hist; hist.fill(0);
const uMin = (cw<ch?cw:ch), span = uMin/5.6;
const cx = P.x*cw, cy = P.y*ch, sc = span*P.scale;
let x=0.1, y=0.0;
for (let it=0; it<30; it++){ const nx=Math.sin(a*y)+c*Math.cos(a*x); const ny=Math.sin(b*x)+d*Math.cos(b*y); x=nx; y=ny; }
let nMax=0, filled=0;
for (let it=0; it<iters; it++){
  const nx = Math.sin(a*y) + c*Math.cos(a*x);
  const ny = Math.sin(b*x) + d*Math.cos(b*y);
  x=nx; y=ny;
  const ix = (cx + x*sc)|0, iy = (cy + y*sc)|0;
  if (ix>=0 && ix<cw && iy>=0 && iy<ch){ const bi=iy*cw+ix; const nv=hist[bi]+1; hist[bi]=nv; if(nv===1)filled++; if(nv>nMax)nMax=nv; }
}

// ---- log-density tone map -> guarded smoothed accumulator (collapse never erases the cloud) ----
S.fc = (S.fc||0) + 1;
const collapsed = (filled/NG < 0.05) && S.fc > 24;   // Clifford can pass through non-chaotic windows -> hold last good cloud
const expo = (0.5 + P.energy*2.0 + intn*0.45) + K.pulse*0.15 + A.rms*0.9;
const invG = 1/Math.max(0.3, P.gamma);
const logMax = Math.log(1 + nMax*expo) + 1e-3;
const mix = 1 - Math.min(0.92, P.persist)*0.82;
const acc = S.acc, st = P.style, pencil = (st==='pencil');
const buf = S.buf; buf.loadPixels(); const q = buf.pixels;
for (let i=0;i<NG;i++){
  if (!collapsed){
    const n = hist[i];
    const br = n>0 ? Math.pow(Math.min(1, Math.log(1+n*expo)/logMax), invG) : 0;
    acc[i] += (br-acc[i])*mix;
  }
  const av = acc[i];
  let R,G,B;
  if (pencil){
    R = 255*(0.91 - av*0.80); G = 255*(0.89 - av*0.80); B = 255*(0.83 - av*0.72);
  } else {
    let k=(av*255)|0; if(k<0)k=0; if(k>255)k=255;
    R = pal[k*3]*255; G = pal[k*3+1]*255; B = pal[k*3+2]*255;
  }
  const p4=i*4;
  q[p4]   = R<0?0:(R>255?255:R);
  q[p4+1] = G<0?0:(G>255?255:G);
  q[p4+2] = B<0?0:(B>255?255:B);
  q[p4+3] = 255;
}
buf.updatePixels();

// ---- display: base full-frame fill (ground + corners) + slowly rotating/breathing cloud on top ----
const rot = S.rot0 + K.t*0.028*P.speed + Math.sin(K.t*0.05)*0.05;
const zoom = 1.0 + 0.035*Math.sin(K.t*0.09 + S.zph) + K.swell*0.02;
push();
if (P.alpha < 100){
  tint(0,0,100,P.alpha);
  translate(width/2, height/2); rotate(rot); scale(zoom);
  image(buf, -width/2, -height/2, width, height);
  noTint();
} else {
  image(buf, 0, 0, width, height);                 // base fills frame; corners hold matching ground tone
  translate(width/2, height/2); rotate(rot); scale(zoom);
  image(buf, -width/2, -height/2, width, height);  // the turning cloud
  if (!pencil){ blendMode(ADD); tint(0,0,100,14+P.energy*18); image(buf, -width/2, -height/2, width, height); noTint(); blendMode(BLEND); }
}
pop();

const D = { wind:.5, scale:1, speed:1, density:.5, energy:.6, hue:210, x:.5, y:.5, pole:'left', style:'weave', act:'breeze', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const clamp = (v,a,b)=> v<a?a:(v>b?b:v);
const skyKey = width+'x'+height+'|'+P.seed+'|'+st+'|'+Math.round(P.hue);

// --- cached full-bleed sky backdrop (static) ---
if (!S.sky || S.skyKey !== skyKey){
  S.skyKey = skyKey;
  const g = createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100);
  g.noStroke();
  const dark = (st==='wireframe')?1:0;
  const topH=(P.hue+165)%360, botH=(P.hue+195)%360;
  for (let y=0;y<height;y+=2){
    const t=y/height;
    g.fill((topH*(1-t)+botH*t)%360, 20+16*t, dark?(9+8*t):(26+20*(1-t)), 100);
    g.rect(0,y,width,2);
  }
  for (let i=0;i<7;i++){
    const cx=fr(i*3+1)*width, cy=fr(i*3+2)*height*0.55, cr=(0.06+fr(i*3+3)*0.13)*u;
    g.fill(0,0,100,dark?3:7);
    g.ellipse(cx,cy,cr*2.6,cr*1.1);
  }
  S.sky=g;
}
image(S.sky,0,0);

// --- flag frame ---
const horiz = (P.pole!=='top');
const Wf = (horiz?0.60:0.42)*u*P.scale;
const Hf = (horiz?0.40:0.58)*u*P.scale;
const x0 = P.x*width - Wf*0.5 + (P.pole==='left'? Wf*0.06:0);
const y0 = P.y*height - Hf*0.5;
const cols = Math.floor(12 + P.density*18);
const rows = Math.floor(8 + P.density*10);

// --- wind (real-time gust envelope on top of steady breeze; audio adds) ---
let spd = P.speed, wmul;
if (P.act==='gust'){ wmul = 0.7 + 1.1*Math.max(0,Math.sin(K.t*0.22)) + K.pulse*0.4; }
else if (P.act==='storm'){ wmul = 1.5 + 0.5*Math.sin(K.t*0.5); spd*=1.3; }
else { wmul = 0.85 + 0.35*Math.sin(K.t*0.18); }
const W = (0.08 + P.wind*0.9)*wmul + A.bass*0.35*P.wind;
const t = K.t;

// --- deform grid every frame (procedural traveling-wave cloth) ---
const pts = S.pts || (S.pts=[]);
let idx=0;
for (let j=0;j<=rows;j++) for (let i=0;i<=cols;i++){
  const gu=i/cols, gv=j/rows;
  const axis = horiz?gu:gv, cross = horiz?gv:gu;
  const flap = axis*axis*0.7 + axis*0.3;
  const ph = axis*2.3 - t*0.9*spd;
  const wave = Math.sin(ph*TWO_PI + cross*1.6) + 0.5*Math.sin(ph*2.1*TWO_PI - cross*1.1 + t*0.4);
  const z = wave*W*flap;
  const shade = Math.cos(ph*TWO_PI + cross*1.6);
  let sx = x0 + gu*Wf, sy = y0 + gv*Hf;
  if (horiz){ sy += z*0.17*Hf; sx -= Math.abs(z)*0.05*Wf; }
  else { sx += z*0.17*Wf; sy -= Math.abs(z)*0.04*Hf; }
  const p = pts[idx] || (pts[idx]={});
  p.x=sx; p.y=sy; p.gu=gu; p.gv=gv; p.sh=shade;
  idx++;
}
const at = (i,j)=>pts[j*(cols+1)+i];

const baseCol = (gu,gv)=>{
  if (st==='stripes'){ const k=Math.floor(gv*7)%2; return k?[P.hue,60,82]:[(P.hue+8)%360,20,96]; }
  if (st==='rising_sun'){ const ang=Math.atan2(gv-0.5,gu+0.03); const k=Math.floor((ang+PI)/(PI/7))%2; return k?[P.hue,82,88]:[(P.hue+25)%360,8,98]; }
  if (st==='checker'){ const k=(Math.floor(gu*6)+Math.floor(gv*6))%2; return k?[P.hue,62,84]:[(P.hue+185)%360,22,92]; }
  return [P.hue,42+P.energy*22,80]; // weave (fold-shaded solid, no outline)
};

if (st==='wireframe'){
  strokeWeight(Math.max(1,u*0.0016)); noFill();
  for (let j=0;j<=rows;j++){ beginShape(); for(let i=0;i<=cols;i++){const p=at(i,j); stroke((P.hue+p.gu*40)%360,70,clamp(60+35*p.sh,20,98),85); vertex(p.x,p.y);} endShape(); }
  for (let i=0;i<=cols;i++){ beginShape(); for(let j=0;j<=rows;j++){const p=at(i,j); stroke((P.hue+p.gu*40)%360,60,clamp(52+30*p.sh,20,98),50); vertex(p.x,p.y);} endShape(); }
