const gh = (i, s) => { let h = (i * 374761393 + s * 668265263 + seedI * 2654435761) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); h ^= h >>> 16; return (h >>> 0) / 4294967296; };

// ---- (re)build the forest on size / seed change ----
const buildSig = CW + 'x' + CH + '_' + seedI;
if (S.buildSig !== buildSig || !S.state) {
  S.buildSig = buildSig;
  S.state = new Uint8Array(NC);   // 0 empty/soil, 1 tree, 2 burning
  S.next = new Uint8Array(NC);
  S.heat = new Uint8Array(NC);    // ember/fire glow, decays
  S.tex = new Uint8Array(NC);     // stable canopy/soil texture
  const st = S.state, tx = S.tex;
  for (let k = 0; k < NC; k++) { st[k] = gh(k, 7) < 0.58 ? 1 : 0; tx[k] = (gh(k, 4242) * 255) | 0; }
  // a handful of initial fire seeds so the very first frame already has fronts
  for (let a = 0; a < 5; a++) { const c = (gh(a + 1, 91) * NC) | 0; if (st[c] === 1) { st[c] = 2; S.heat[c] = 255; } }
  S.step = null;
}

// ---- section-driven dramaturgy: fire seasons (dry burn / wet regrow), palette drift ----
const secPhase = K.section * 0.9 + K.t * 0.021;
const season = 0.5 + 0.5 * Math.sin(secPhase);                 // 0 wet .. 1 dry
const hueOff = P.hue + K.section * 9 + K.t * 1.2;
const growthP = 0.010 + P.density * 0.045 + (1 - season) * 0.028;
let strikes = Math.max(1, Math.round(0.3 + P.density * 1.3 + season * 1.7 + K.intensity * 1.1 + A.bass * 4));
const spreadPow = 0.55 + P.spread * 0.42;                       // fire-catch probability
const sx = (P.x * CW) | 0, sy = (P.y * CH) | 0;                 // storm-center bias for strikes
const stormR = Math.round((0.16 + (1 - P.spread) * 0.34) * Math.min(CW, CH));

// ---- clock -> generations/sec (continuous K.t drives evolution; never re-phases) ----
const gps = 2.5 + P.speed * 5 + K.intensity * 2.5;
const target = Math.floor(K.t * gps);

// ---- one synchronous CA generation ----
function evolve(gen) {
  const st = S.state, nx = S.next, ht = S.heat;
  for (let j = 0; j < CH; j++) {
    const jm = (j - 1 + CH) % CH, jp = (j + 1) % CH, rj = j * CW, rjm = jm * CW, rjp = jp * CW;
    for (let i = 0; i < CW; i++) {
      const idx = rj + i, s = st[idx];
      if (s === 2) { nx[idx] = 0; }                               // burning -> ash
      else if (s === 1) {                                         // tree: catch from any burning Moore neighbor
        const im = (i - 1 + CW) % CW, ip = (i + 1) % CW;
        let burn = 0;
        if (st[rjm + im] === 2 || st[rjm + i] === 2 || st[rjm + ip] === 2 ||
            st[rj + im] === 2 || st[rj + ip] === 2 ||
            st[rjp + im] === 2 || st[rjp + i] === 2 || st[rjp + ip] === 2) burn = 1;
        nx[idx] = (burn && gh(idx, gen * 5 + 1) < spreadPow) ? 2 : 1;
      } else {                                                    // ash/soil -> regrow tree
        nx[idx] = gh(idx, gen) < growthP ? 1 : 0;
      }
    }
  }
  // lightning strikes near the storm center ignite trees
  for (let a = 0; a < strikes; a++) {
    const ang = gh(a * 3 + 1, gen * 7 + 2) * 6.283, rr = gh(a * 3 + 2, gen * 7 + 5);
    const ci = ((sx + Math.round(Math.cos(ang) * rr * stormR)) % CW + CW) % CW;
    const cj = ((sy + Math.round(Math.sin(ang) * rr * stormR)) % CH + CH) % CH;
    const ci2 = ci * 1, cidx = cj * CW + ci2;
    if (nx[cidx] === 1) nx[cidx] = 2;
  }
  // heat: spike on burning, exponential ember decay elsewhere
  for (let k = 0; k < NC; k++) { if (nx[k] === 2) ht[k] = 255; else { const hv = ht[k]; ht[k] = hv > 4 ? (hv * 176) >> 8 : 0; } }
  const tmp = S.state; S.state = S.next; S.next = tmp;
}

// ---- advance generations (guard t0 resets, cap catch-up so a time-jump can't torch everything) ----
if (S.step == null || target < S.step) S.step = target;
if (target - S.step > 8) { S.step = target; }
else { let guard = 0; while (S.step < target && guard < 4) { evolve(S.step); S.step++; guard++; } }

// ---- coarse buffer ----
if (!S.g || S.gw !== CW || S.gh !== CH) { S.g = createGraphics(CW, CH); S.g.pixelDensity(1); S.gw = CW; S.gh = CH; }

// ---- HSV -> rgb 0..255 (no per-pixel alloc), exposure + global hue offset baked in ----
const OUT = [0, 0, 0];
const eexp = Math.min(1.45, 0.55 + P.energy * 0.85 + K.intensity * 0.2 + A.rms * 0.4);
function put(h, s, v) {
  h = ((h + hueOff) % 360 + 360) % 360; v = Math.min(1, v * eexp); s = s < 0 ? 0 : (s > 1 ? 1 : s);
  const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 60) { r = c; g = x; b = 0; } else if (h < 120) { r = x; g = c; b = 0; } else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; } else if (h < 300) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
  OUT[0] = (r + m) * 255; OUT[1] = (g + m) * 255; OUT[2] = (b + m) * 255;
}
function fire(hn) { put(6 + hn * 50, 1.15 - hn * 0.6, 0.1 + hn * 1.05); }
function thermal(v) { v = v < 0 ? 0 : (v > 1 ? 1 : v); put(250 - v * 250, v > 0.85 ? 0.9 - (v - 0.85) * 5 : 0.9, 0.24 + v * 0.72); }

const style = P.style;
let col;
if (style === 'ember-night') {
  col = (s, hn, tv) => { if (s === 2) fire(hn); else if (s === 1) put(126 + tv * 34, 0.85, 0.09 + tv * 0.06); else if (hn > 0.05) fire(hn); else put(18, 0.7, 0.018 + hn); };
} else if (style === 'autumn') {
  col = (s, hn, tv) => { if (s === 2) put(4 + hn * 34, 1.1 - hn * 0.45, 0.14 + hn * 0.92); else if (s === 1) put(24 + tv * 26, 0.82, 0.3 + tv * 0.2); else if (hn > 0.07) put(8 + hn * 26, 0.88, hn * 0.86 + 0.05); else put(20, 0.5, 0.09 + tv * 0.03); };
} else if (style === 'toxic') {
  col = (s, hn, tv) => { if (s === 2) put(150 + hn * 44, 1 - hn * 0.5, 0.16 + hn * 0.9); else if (s === 1) put(154 + tv * 42, 0.72, 0.26 + tv * 0.18); else if (hn > 0.07) put(168 + hn * 30, 0.82, hn * 0.82 + 0.05); else put(284, 0.5, 0.085 + tv * 0.03); };
} else if (style === 'heatmap') {
  col = (s, hn, tv) => { if (s === 2) thermal(1); else if (s === 0) thermal(hn * 0.82); else thermal(0.30 + tv * 0.08); };
} else { // wildfire (default)
  col = (s, hn, tv) => { if (s === 2) fire(hn); else if (s === 1) put(92 + tv * 44, 0.55 + tv * 0.25, 0.34 + tv * 0.2); else if (hn > 0.06) fire(hn); else put(24, 0.45, 0.1 + tv * 0.03); };
}

// ---- render buffer (rebuild on generation / live-poke change) ----
const rsig = S.step + '|' + style + '|' + Math.round(hueOff) + '|' + Math.round(eexp * 20) + '|' + CW + 'x' + CH;
if (S.rsig !== rsig) {
  S.rsig = rsig;
  const g = S.g; g.loadPixels(); const px = g.pixels, st = S.state, ht = S.heat, tx = S.tex;
  for (let k = 0; k < NC; k++) {
    col(st[k], ht[k] / 255, tx[k] / 255);
    const o = 4 * k; px[o] = OUT[0]; px[o + 1] = OUT[1]; px[o + 2] = OUT[2]; px[o + 3] = 255;
  }
  g.updatePixels();
}

// ---- draw: upscale with bounded zoom-breath + micro-rotation (motion floor insurance, no black edges) ----
const ang = Math.sin(K.t * 0.05) * 0.05;
const zoom = 1.14 + Math.sin(K.t * 0.09) * 0.03 + A.rms * 0.1;
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
translate(width / 2, height / 2);
rotate(ang);
scale(zoom);
imageMode(CENTER);
image(S.g, 0, 0, width, height);
pop();
imageMode(CORNER);

// ---- audio warmth ON TOP of the clk baseline (all-zero during validation; partial alpha, never strobes) ----
if (A.bass > 0.01 || A.treble > 0.01 || A.rms > 0.01) {
  push(); blendMode(ADD); noStroke();
  fill((hueOff + 24) % 360, 55, 100, (A.bass * 0.55 + A.rms * 0.35) * P.energy * 16);
  rect(0, 0, width, height);
  fill((hueOff + 50) % 360, 25, 100, A.treble * P.energy * 11);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}

const D = { density:.55, energy:.6, speed:1, scale:1, wind:.5, hue:330, x:.5, y:.5, style:'blossom', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const wh = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const style = P.style;
const sec = K.section | 0;

// per-frame deterministic PRNG (reset each frame so the tree STRUCTURE is stable; wind is added separately)
let sr;
function rreset(){ sr = ((P.seed + 1 + sec*777) * 2654435761) >>> 0; }
function rnd(){ sr ^= sr<<13; sr>>>=0; sr ^= sr>>17; sr ^= sr<<5; sr>>>=0; return sr/4294967295; }

// wind: SUM of incommensurate sinusoids so the pose NEVER re-phases at the 8s validation window
const wt = K.t;
const gust = 0.9*Math.sin(wt*0.61) + 0.5*Math.sin(wt*1.43 + 1.7) + 0.32*Math.sin(wt*2.29 + 0.4);
const windAmp = (0.05 + P.wind*0.16) * (1 + A.lowmid*0.5);
const maxDepth = 9 + Math.round(P.density*2);           // 9..11
const ratio = 0.70 + P.scale*0.06;
const spread = 0.34 + P.wind*0.10;
const len0 = height * (0.16 + P.scale*0.07);
const hb = P.hue;

// ---- sky/ground ground so it's never near-black and fills frame ----
let sky0, sky1, grd0;
if (style === 'blossom')      { sky0='#101a2e'; sky1='#26304e'; grd0='#0b0d16'; }
else if (style === 'autumn')  { sky0='#241426'; sky1='#3a2030'; grd0='#120a10'; }
else if (style === 'bio')     { sky0='#02060a'; sky1='#04121a'; grd0='#010406'; }
else if (style === 'winter')  { sky0='#0c1420'; sky1='#1c2c3e'; grd0='#0a0e14'; }
else                          { sky0='#efe9dc'; sky1='#dcd2c0'; grd0='#cfc4ae'; } // ink (paper)
const dc = drawingContext;
const gg = dc.createLinearGradient(0,0,0,height);
gg.addColorStop(0, sky0); gg.addColorStop(0.62, sky1); gg.addColorStop(1, grd0);
dc.save(); dc.fillStyle = gg; dc.fillRect(0,0,width,height); dc.restore();

const inkMode = (style === 'ink');
const rootX = width * P.x, rootY = height * (0.995);
push();
if (inkMode) blendMode(BLEND); else blendMode(ADD);
strokeCap(ROUND);

function branch(x, y, ang, len, depth) {
  const df = maxDepth - depth;                          // 0 at root -> maxDepth at tips
  const tf = df / maxDepth;
  // sway grows toward the tips (cumulative feel) + a per-node phase for organic variation
  const nodePhase = rnd() * 6.28;
  const sway = windAmp * (0.15 + tf*tf*1.6) * (gust + 0.4*Math.sin(wt*1.9 + nodePhase));
  const a = ang + sway;
  const ex = x + Math.cos(a) * len, ey = y - Math.sin(a) * len;

  const w = Math.max(0.5, (maxDepth - df) * 0.9 * (0.6 + P.scale*0.5));
  // trunk brown -> tip hue
  let sh, ss, sv, sa;
  if (inkMode) { sh = 30; ss = 8; sv = 12; sa = 90; }
  else if (style === 'bio') { sh = wh(hb + 70 + tf*60); ss = 70; sv = 40 + tf*60; sa = 30 + tf*30; }
  else { const trunk = 26; sh = wh(trunk + (hb - trunk)*tf); ss = 30 + tf*45; sv = 22 + tf*55; sa = 26 + tf*34; }
  stroke(sh, ss, sv, sa * (0.6 + P.energy*0.6));
  strokeWeight(w);
  line(x, y, ex, ey);

  if (depth <= 0 || len < u*0.012) {
    // foliage tip: blossom / leaf dot
    const bs = u * (0.006 + rnd()*0.012) * (0.7 + P.density*0.9);
    noStroke();
    let fh, fs, fv, fa;
    if (inkMode)              { fh=30; fs=6; fv=20; fa=40; }
    else if (style==='autumn'){ fh=wh(18 + rnd()*36); fs=85; fv=95; fa=55; }
    else if (style==='bio')   { fh=wh(hb+120+rnd()*80); fs=80; fv=100; fa=60; }
    else if (style==='winter'){ fh=wh(200+rnd()*30); fs=20; fv=100; fa=55; }
    else                      { fh=wh(hb + (rnd()-0.5)*40); fs=60+rnd()*30; fv=95; fa=55; } // blossom
    const tw = fa + A.treble*30 + K.pulse*10;
    fill(fh, fs, fv, Math.min(90, tw));
    circle(ex + (rnd()-0.5)*bs, ey + (rnd()-0.5)*bs, bs*2);
    return;
  }
  const nb = (rnd() < 0.30 && df < maxDepth-2) ? 3 : 2;  // occasional trifurcation
  const nl = len * (ratio + (rnd()-0.5)*0.06);
  const sp = spread * (0.7 + rnd()*0.6);
  branch(ex, ey, a + sp, nl, depth-1);
  branch(ex, ey, a - sp*(0.8+rnd()*0.4), nl, depth-1);
  if (nb === 3) branch(ex, ey, a + (rnd()-0.5)*0.3, nl*0.9, depth-1);
}

rreset();
branch(rootX, rootY, Math.PI/2 + 0.10*Math.sin(wt*0.37), len0, maxDepth);
blendMode(BLEND);
pop();

const D = { density: .55, energy: .6, speed: 1, rows: 11, scale: 1, hue: 30, x: .5, y: .5, style: 'neon', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const wrap = h => ((h % 360) + 360) % 360;

// --- real-time dt (guard t0 resets / big jumps) ---
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t - 1/60;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt > 0) || dt > 0.4) dt = 1/60;

// --- layout ---
const W = width, H = height, u = Math.min(W, H);
const R = Math.max(5, Math.min(18, Math.round(P.rows)));
const NB = R + 1;
const cx = P.x * W;
const boardW = Math.min(W * 0.94, u * 1.75) * (0.55 + P.scale * 0.5);
const binW = boardW / NB;
const yc = (P.y - 0.5) * H * 0.26;
const yTop = H * 0.10 + yc;
const yPegBot = H * 0.60 + yc;
const yBot = H * 0.965 + yc;
const rowH = (yPegBot - yTop) / R;
const hueSpread = 66;
const capCount = 90;
const aMul = Math.max(0, Math.min(1, P.alpha / 100));

// --- seed / structure init & rebuild ---
if (S.seedUsed !== P.seed || !S.bins || S.nb !== NB) {
  S.seedUsed = P.seed; S.balls = []; S.bins = new Float32Array(NB);
  S.nextId = 0; S.nb = NB; S.emitAcc = 0; S.drain = false;
}

// --- style palette ---
const sec = (K.section | 0);
const secHue = sec * 13;
const style = P.style;
let wire = false, mono = false, thermal = false;
let bgT, bgB, pegC, sat, hueBase;
if (style === 'gold') {
  mono = true; sat = 88; hueBase = 44; bgT = [42,60,5]; bgB = [38,55,14]; pegC = [45,70,24];
} else if (style === 'thermal') {
  thermal = true; sat = 90; hueBase = 40; bgT = [222,72,7]; bgB = [248,52,17]; pegC = [210,45,28];
} else if (style === 'phosphor') {
  mono = true; sat = 92; hueBase = 132; bgT = [135,82,5]; bgB = [140,70,14]; pegC = [135,85,22];
} else if (style === 'blueprint') {
  wire = true; sat = 72; hueBase = 190; bgT = [214,76,9]; bgB = [210,64,18]; pegC = [192,78,62];
} else { // neon (default) — colorful column-hued beans
  sat = 85; hueBase = wrap(P.hue + secHue);
  bgT = [wrap(P.hue + secHue + 205), 58, 6]; bgB = [wrap(P.hue + secHue + 245), 46, 15]; pegC = [wrap(P.hue + secHue), 42, 32];
}

// --- emission ---
const inten = 0.5 + K.intensity * 0.6 + A.bass * 0.5;
let rate = (3 + P.density * 46) * inten * (0.5 + P.speed * 0.6);
if (S.drain) rate *= 0.12;
const maxBalls = 40 + Math.floor(P.density * 150);
S.emitAcc += rate * dt;
let guard = 0;
while (S.emitAcc >= 1 && S.balls.length < maxBalls && guard++ < 30) {
  S.emitAcc -= 1;
  const jit = (fr(S.nextId * 7.3) - 0.5) * binW * 0.35;
  S.balls.push({ id: S.nextId++, x: cx + jit, y: yTop, off: 0, row: 0, vy: 18 + fr(S.nextId * 3.1) * 34 });
}

// --- physics: fall + peg deflection + accrete into bins ---
const grav = (yPegBot - yTop) * 1.7;
const spd = P.speed * (0.7 + K.intensity * 0.4);
const alive = [];
for (const b of S.balls) {
  b.vy += grav * dt * spd;
  b.y += b.vy * dt * spd;
  while (b.row < R && b.y >= yTop + (b.row + 0.5) * rowH) {
    const dir = fr(b.id * 131.7 + b.row * 57.3 + 0.5) < 0.5 ? -1 : 1;
    b.off += dir * 0.5; b.row++;
  }
  const tx = cx + b.off * binW;
  b.x += (tx - b.x) * Math.min(1, dt * 15 * spd + 0.04);
  if (b.y >= yPegBot) {
    let bin = Math.round(b.off + R / 2); bin = Math.max(0, Math.min(R, bin));
    S.bins[bin] += 1;
    continue;
  }
  alive.push(b);
}
S.balls = alive;

// --- drain / refill cycle (smooth, non-strobe) ---
let maxc = 0; for (let i = 0; i < NB; i++) if (S.bins[i] > maxc) maxc = S.bins[i];
if (!S.drain && maxc >= capCount) S.drain = true;
if (S.drain) {
  const k = Math.pow(0.4, dt);
  for (let i = 0; i < NB; i++) S.bins[i] *= k;
  if (maxc * k < capCount * 0.03) S.drain = false;
}

// ================= RENDER =================
push();

// background ground tone (opaque fill for genart; skipped when compositing translucent)
if (P.alpha >= 100) {
  noStroke();
  const bands = 44, drift = 2 + K.swell * 3;
  for (let i = 0; i < bands; i++) {
    const f = i / (bands - 1);
    const h = wrap(bgT[0] + (bgB[0] - bgT[0]) * f);
    const s = bgT[1] + (bgB[1] - bgT[1]) * f;
    const br = bgT[2] + (bgB[2] - bgT[2] + drift * f) * f;
    fill(h, s, br);
    rect(0, i * (H / bands) - 0.5, W, H / bands + 1.5);
  }
}

// faint peg lattice
if (wire) {
  stroke(pegC[0], pegC[1], pegC[2], 30 * aMul); strokeWeight(1);
  const pr = Math.max(2, binW * 0.14);
  for (let r = 0; r < R; r++) for (let k = 0; k <= r; k++) {
    const px = cx + (k - r / 2) * binW, py = yTop + (r + 0.5) * rowH;
    line(px - pr, py, px + pr, py); line(px, py - pr, px, py + pr);
  }
} else {
  noStroke(); fill(pegC[0], pegC[1], pegC[2], 20 * aMul);
  const pr = Math.max(1.5, binW * 0.12);
  for (let r = 0; r < R; r++) for (let k = 0; k <= r; k++) {
    const px = cx + (k - r / 2) * binW, py = yTop + (r + 0.5) * rowH;
    ellipse(px, py, pr * 2, pr * 2);
  }
}

// histogram bars (lit by count)
const spark = A.treble * 0.6 + K.pulse * 0.25;
for (let bIdx = 0; bIdx < NB; bIdx++) {
  const frac = Math.max(0, Math.min(1, S.bins[bIdx] / capCount));
  if (frac < 0.004) continue;
  const barH = frac * (yBot - yPegBot);
  const bx = cx + (bIdx - R / 2) * binW;
  const bw = binW * 0.86;
  const ytopB = yBot - barH;
  let bh, bs, bb;
  if (thermal) { bh = wrap(240 - frac * 240); bs = 92 - frac * 34; bb = 40 + frac * 55; }
  else if (mono) { bh = hueBase; bs = sat; bb = 28 + frac * 62; }
  else if (wire) { bh = wrap(hueBase + ((bIdx / (NB - 1)) - 0.5) * 2 * hueSpread); bs = sat; bb = 55; }
  else { bh = wrap(hueBase + ((bIdx / (NB - 1)) - 0.5) * 2 * hueSpread); bs = sat; bb = 34 + frac * 60; }
  const bexp = Math.min(100, bb + P.energy * 22 + A.rms * 30);
  if (wire) {
    noFill(); stroke(bh, bs, bexp, 80 * aMul); strokeWeight(Math.max(1, binW * 0.05));
    rect(bx - bw / 2, ytopB, bw, barH);
    line(bx - bw / 2, yBot, bx + bw / 2, ytopB);
  } else {
