    r=242*tone+3; g=232*tone+3; bl=206*tone+3;
  }
  const j=i*4; px[j]=clp(r,0,255); px[j+1]=clp(g,0,255); px[j+2]=clp(bl,0,255); px[j+3]=255;
}
buf.updatePixels();

// ---- composite: upscale to full frame; P.scale = display zoom on a centered sub-rect ----
const zoom=clp(P.scale,1,2.6), sw=GW/zoom, sh=GH/zoom;
const sx=clp((GW-sw)*(0.15+P.x*0.7),0,GW-sw), sy=clp((GH-sh)*(0.15+P.y*0.7),0,GH-sh);
noStroke(); drawingContext.imageSmoothingEnabled=true;
push();
if(P.alpha<100) tint(0,0,100,clp(P.alpha,0,100));
image(buf,0,0,W,H,sx,sy,sw,sh);
pop();

// ---- finishing (PARTIAL-frame only — never a full-frame flash) ----
if(st!=='ink-maze'){
  blendMode(ADD); noStroke();
  const hb=(((P.hue%360)+360)%360);
  const gl=clp((7+9*K.swell+A.bass*16+A.rms*10)*0.6,0,13);
  fill(hb, st==='bone'?18:42, 100, gl);
  rect(0,0,W,H);
  blendMode(BLEND);
} else { // cream never reads flat: faint warm vignette frame
  noFill(); strokeWeight(u*0.14); stroke(35,12,52,9); rect(-u*0.07,-u*0.07,W+u*0.14,H+u*0.14); noStroke();
}
blendMode(BLEND); drawingContext.shadowBlur=0; noStroke();

const D = { energy:.6, density:.55, scale:1, speed:1, hue:212, spray:.6, fuji:1, boats:1, x:.34, y:.68, style:'woodblock', act:'swell', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W=width, H=height, u=Math.min(W,H), TAU=Math.PI*2;
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;
const st=P.style, intn=(K.intensity!=null?K.intensity:.6);

// ---- palette per style (rendering philosophy, not just hue) ----
function pal(s){
  if(s==='sepia')     return {sky:[[34,14,90],[30,30,72]], deep:[28,52,26], mid:[30,44,46], lip:[32,32,66], foam:[36,10,93], key:[26,55,16], line:[28,50,22], fuji:[30,20,60], cap:[35,6,92]};
  if(s==='sumi')      return {sky:[[38,5,93],[36,8,80]], deep:[220,10,14], mid:[222,8,34], lip:[224,6,52], foam:[40,3,94], key:[225,10,10], line:[224,10,20], fuji:[224,6,48], cap:[40,3,92]};
  if(s==='blueprint') return {sky:[[220,72,10],[218,78,7]], deep:[198,70,80], mid:[198,64,72], lip:[196,60,90], foam:[190,40,98], key:[196,66,88], line:[200,60,60], fuji:[196,55,70], cap:[190,30,98]};
  if(s==='storm')     return {sky:[[218,34,20],[222,42,10]], deep:[212,55,16], mid:[204,44,30], lip:[196,30,48], foam:[186,14,80], key:[220,40,8], line:[210,30,26], fuji:[214,24,36], cap:[196,10,74]};
  return {sky:[[36,16,93],[204,34,74]], deep:[218,82,30], mid:[210,72,54], lip:[204,52,74], foam:[42,7,98], key:[222,46,12], line:[220,55,22], fuji:[212,30,58], cap:[40,6,95]};
}
const C=pal(st);
const key=W+'x'+H+'.'+st+'.'+(P.fuji|0)+'.'+P.seed;

// ---- baked sky + Fuji buffer (built once per key) ----
if(!S.bg || S.bgKey!==key){
  S.bgKey=key;
  const g=createGraphics(W,H); g.colorMode(HSB,360,100,100,100); g.noStroke();
  for(let yy=0; yy<H; yy+=2){
    const t=yy/H, a=C.sky[0], b=C.sky[1];
    g.fill(a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t);
    g.rect(0,yy,W,2);
  }
  if(st==='blueprint'){
    g.stroke(C.line[0],C.line[1],C.line[2],26); g.strokeWeight(1);
    const gs=Math.max(28,u*0.07);
    for(let gx=0;gx<W;gx+=gs) g.line(gx,0,gx,H);
    for(let gy=0;gy<H;gy+=gs) g.line(0,gy,W,gy);
    g.noStroke();
  }
  if(P.fuji>0.5){
    const fx=W*0.66, fh=u*0.34, fw=u*0.62, base=H*0.62;
    if(st==='blueprint'){
      g.noFill(); g.stroke(C.fuji[0],C.fuji[1],C.fuji[2],70); g.strokeWeight(1.4);
      g.triangle(fx-fw/2,base, fx,base-fh, fx+fw/2,base);
      g.noStroke();
    } else {
      g.fill(C.fuji[0],C.fuji[1],C.fuji[2],86);
      g.triangle(fx-fw/2,base, fx,base-fh, fx+fw/2,base);
      // snow cap
      g.fill(C.cap[0],C.cap[1],C.cap[2],94);
      const cy=base-fh*0.66, cw=fw*0.34;
      g.beginShape();
      g.vertex(fx-cw,cy+fh*0.1); g.vertex(fx-cw*0.4,cy-fh*0.02); g.vertex(fx-cw*0.15,cy+fh*0.06);
      g.vertex(fx+cw*0.2,cy-fh*0.03); g.vertex(fx+cw*0.55,cy+fh*0.07); g.vertex(fx+cw,cy+fh*0.11);
      g.vertex(fx,cy-fh*0.16);
      g.endShape(CLOSE);
    }
  }
  S.bg=g;
}
image(S.bg,0,0);

// ---- crash phase (rise->crest->recede once per bar); K.t drift = never re-phases ----
const rate=0.25*P.speed;
const cp=(((K.beat*rate)%1)+1)%1;
const amp01=Math.sin(cp*Math.PI);                    // 0..1..0 over the bar
const curl01=cp>0.5 ? Math.sin((cp-0.5)/0.5*Math.PI) : 0;
const en=clp(P.energy,0,1);
const ampMul = P.act==='calm' ? 0.55 : (P.act==='typhoon' ? 1.25 : 1);
const swAmp=(0.16+en*0.34)*ampMul*(0.7+intn*0.5) + A.rms*0.5;   // hump reach as frac of u
const baseY=H*clp(P.y,0.4,0.9);
const hx=W*clp(P.x,0.15,0.6);
const hump=u*swAmp*(0.35+amp01*0.85);
const tcrash=curl01*(0.6+en) + A.bass*0.6;

noStroke();
// ---- distant swell wall behind the claw (mid tone) ----
function surface(yBase, humpAmt, spreadK, rip){
  beginShape();
  vertex(0,H);
  const step=Math.max(9,W/130);
  for(let x=-step;x<=W+step;x+=step){
    const d=(x-hx)/(u*spreadK);
    const bell=Math.exp(-d*d);
    const ripple=Math.sin(x*0.012 + K.t*0.9*P.speed)*rip + Math.sin(x*0.031 - K.t*1.5)*rip*0.5;
    const y=yBase - humpAmt*bell - ripple*u*0.012 + u*0.02*Math.sin(x*0.006+K.t*0.4);
    vertex(x,y);
  }
  vertex(W,H); vertex(0,H);
  endShape(CLOSE);
}
if(st==='blueprint'){
  noFill(); stroke(C.mid[0],C.mid[1],C.mid[2],55); strokeWeight(1.2);
  surface(baseY+u*0.05, hump*0.6, 0.9, 0.7);
  stroke(C.deep[0],C.deep[1],C.deep[2],85); strokeWeight(1.6);
  surface(baseY, hump, 0.6, 1.0);
  noStroke();
} else {
  fill(C.mid[0],C.mid[1],C.mid[2], st==='sumi'?60:88);
  surface(baseY+u*0.06, hump*0.55, 0.95, 0.7);
  fill(C.deep[0],C.deep[1],C.deep[2], st==='sumi'?72:96);
  surface(baseY, hump, 0.6, 1.0);
}

// ---- the claw: overhanging lip + curling fingers at the crest ----
const crestY=baseY-hump*0.86, crestX=hx;
push();
translate(crestX,crestY);
const reach=u*(0.16+en*0.16)*(0.6+amp01);
const droop=u*(0.10+tcrash*0.16);
if(st==='blueprint'){
  noFill(); stroke(C.lip[0],C.lip[1],C.lip[2],80); strokeWeight(1.6);
  beginShape();
  vertex(0,0);
  bezierVertex(reach*0.4,-u*0.10, reach*1.05,-u*0.06, reach*1.2, u*0.02);
  bezierVertex(reach*1.28, droop*0.7, reach*1.0, droop, reach*0.7, droop*0.9);
  endShape();
} else {
  fill(C.lip[0],C.lip[1],C.lip[2], st==='sumi'?70:92);
  beginShape();
  vertex(0,0);
  bezierVertex(reach*0.35,-u*0.12, reach*1.0,-u*0.07, reach*1.22,-u*0.005);
  bezierVertex(reach*1.34,droop*0.85, reach*0.98,droop*1.05, reach*0.66,droop*0.9);
  bezierVertex(reach*0.5,droop*0.5, reach*0.55,-u*0.01, 0,0);
  endShape(CLOSE);
}
// Hokusai claw fingers: parametric log-spirals of foam
const nFing=Math.round(3+P.density*7);
for(let f=0; f<nFing; f++){
  const ft=f/(nFing-1||1);
  const fxp=reach*(0.55+ft*0.75);
  const fyp=-u*0.02 + droop*ft*0.5;
  const fingLen=u*(0.03+0.05*fr(f*3.1))*(0.7+curl01*0.9);
  const dir=(fr(f*7.7)<0.5?1:-1);
  push(); translate(fxp,fyp);
  if(st==='blueprint'){ noFill(); stroke(C.foam[0],C.foam[1],C.foam[2],70); strokeWeight(1.1); }
  else { noStroke(); }
  let px=0,py=0;
  const turns=1.6+fr(f*2.3)*1.4;
  const segs=10;
  for(let s2=0;s2<=segs;s2++){
    const a=s2/segs*TAU*turns;
    const r=fingLen*(s2/segs)*0.7;
    const nx=Math.cos(a*dir + K.t*0.4)*r, ny=-Math.sin(a*dir + K.t*0.4)*r - fingLen*(s2/segs);
    if(st==='blueprint'){ if(s2>0) line(px,py,nx,ny); }
    else { fill(C.foam[0],C.foam[1],C.foam[2], 60+30*(s2/segs)); circle(nx,ny, fingLen*0.16*(1-s2/segs*0.4)+1.2); }
    px=nx;py=ny;
  }
  pop();
}
pop();

// keyblock contour on the deep wave (woodblock/sepia carved outline)
if(st==='woodblock'||st==='sepia'){
  noFill(); stroke(C.key[0],C.key[1],C.key[2],70); strokeWeight(Math.max(1.4,u*0.0024));
  surface(baseY, hump, 0.6, 1.0);
  noStroke();
}

// ---- foam spray on the crash (seed-deterministic dots, drift on K.t) ----
const nSpray=Math.round((16+P.spray*70)*(0.3+tcrash));
if(nSpray>0){
  if(st==='blueprint'){ stroke(C.foam[0],C.foam[1],C.foam[2],75); strokeWeight(1.4); } else noStroke();
  for(let i=0;i<nSpray;i++){
    const life=(fr(i*1.7)+K.t*(0.4+P.speed*0.5))%1;
    const ang=-Math.PI*0.5 + (fr(i*4.4)-0.5)*1.3;
    const sp=u*(0.06+fr(i*9.1)*0.16)*(0.6+tcrash);
    const sx=crestX+reach*0.9 + Math.cos(ang)*sp*life + (fr(i*13.7)-0.5)*u*0.08;
    const sy=crestY-u*0.05 + Math.sin(ang)*sp*life + life*life*u*0.16 - u*0.04;
    const al=(1-life)*80*(0.4+tcrash);
    if(st==='blueprint'){ if(al>4) point(sx,sy); }
    else { fill(C.foam[0],C.foam[1],C.foam[2],al); circle(sx,sy, u*0.006*(1-life)+1.4); }
  }
}

// ---- drifting cloud streaks (real-time motion floor, few shapes) ----
noStroke();
const cloudA=st==='blueprint'?0:1;
if(cloudA){
  for(let c=0;c<4;c++){
    const cw=u*(0.22+fr(c*3.3)*0.2);
    const cy=H*(0.12+fr(c*5.1)*0.24);
    let cx=(fr(c*8.8)*W + K.t*u*(0.006+fr(c*2.2)*0.01)*P.speed)%(W+cw*2)-cw;
    fill(C.foam[0], C.foam[1]*0.5, C.foam[2], 7+2*Math.sin(K.t*0.3+c));
    ellipse(cx,cy,cw,cw*0.34);
    ellipse(cx+cw*0.3,cy+u*0.01,cw*0.7,cw*0.28);
  }
}

// ---- optional boats bobbing in the troughs ----
if(P.boats>0.5 && st!=='blueprint'){
  const nB=2;
  for(let b=0;b<nB;b++){
    const bx=W*(0.5+b*0.16)+Math.sin(K.t*0.4+b)*u*0.01;
    const by=baseY+u*0.02 + Math.sin(K.t*1.1+b*2)*u*0.012;
    const bw=u*0.09;
    push(); translate(bx,by); rotate(Math.sin(K.t*0.9+b)*0.12);
    fill(C.key[0],C.key[1],C.key[2],80); noStroke();
    beginShape();
    vertex(-bw*0.5,0); vertex(bw*0.5,0); vertex(bw*0.34,bw*0.13); vertex(-bw*0.34,bw*0.13);
    endShape(CLOSE);
    // a few oarsmen dashes
    stroke(C.key[0],C.key[1],C.key[2],70); strokeWeight(Math.max(1.4,u*0.004));
    for(let o=-1;o<=1;o++) line(o*bw*0.2,-bw*0.02,o*bw*0.2,-bw*0.09);
    noStroke();
    pop();
  }
}

blendMode(BLEND);
drawingContext.shadowBlur=0;

const D = { scale:1, density:.7, energy:.72, speed:1, warp:.55, hue:172, x:.5, y:.5, style:'engraved', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const wh = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const style = P.style;
const cx = width * P.x, cy = height * P.y;

// full-canvas buffer (crisp fine lines + clean alpha compositing) keyed on size
if (!S.buf || S.bkey !== width + 'x' + height) {
  S.buf = createGraphics(width, height);
  S.buf.colorMode(HSB, 360, 100, 100, 100);
  S.buf.pixelDensity(1);
  S.bkey = width + 'x' + height;
}
const g = S.buf;

// seed + density deterministic ring family (rebuild on seed OR ring-count change)
const M = Math.max(3, Math.round(4 + P.density * 8));
if (S.seedUsed !== P.seed || S.M !== M) {
  S.seedUsed = P.seed; S.M = M;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.ring = [];
  for (let k = 0; k < M; k++) {
    S.ring.push({
      petals: 5 + Math.round(fr(k * 5 + 1) * 15),   // 5..20 lobes
      phase0: fr(k * 5 + 2) * TAU,
      ampMul: 0.6 + fr(k * 5 + 3) * 0.95,
      hoff: (fr(k * 5 + 4) - 0.5) * 60,
      dir: fr(k * 5 + 5) < 0.5 ? 1 : -1
    });
  }
  S.rm = 5 + Math.round(fr(900) * 8);               // central rosette harmonic 5..13
  S.rc = 0.34 + fr(901) * 0.46;                     // secondary amplitude ratio
  S.hoff2 = (fr(902) - 0.5) * 30;
}

// continuous motion — linear in K.t so it NEVER re-phases (guilloche precession)
const prec  = K.t * (0.014 + P.speed * 0.030) + 0.12 * Math.sin(K.t * 0.045);
const drift = K.t * (0.05 + P.speed * 0.07);
const rosPhi = K.t * (0.09 + P.speed * 0.09);
const sec = K.section;
const inten = 0.4 + K.intensity * 0.6;
const hb = wh(P.hue + S.hoff2 + sec * 14);
const eg = 0.6 + P.energy * 0.7;
const additive = (style === 'engraved' || style === 'neon' || style === 'iridescent');

g.clear();
g.blendMode(BLEND);
g.noFill();

// ground — native radial gradient (one GPU op, toned so the frame is never near-black)
let cin, cout;
if (style === 'engraved') { cin = '#123c50'; cout = '#03101c'; }     // deep petrol -> near-black
else if (style === 'currency') { cin = '#1d2a14'; cout = '#060a04'; } // dark security-print (reinterpreted bold)
else if (style === 'etch') { cin = '#f3efe5'; cout = '#d6d0c1'; }     // classic pale intaglio
else if (style === 'blueprint') { cin = '#12365f'; cout = '#071224'; }
else if (style === 'neon') { cin = '#0d0d24'; cout = '#040410'; }
else { cin = '#171129'; cout = '#05030c'; } // iridescent
const dc = g.drawingContext;
const grd = dc.createRadialGradient(cx, cy, u * 0.02, cx, cy, Math.hypot(width, height) * 0.62);
grd.addColorStop(0, cin); grd.addColorStop(1, cout);
dc.fillStyle = grd; dc.fillRect(0, 0, width, height);

// radii — outer reaches the corners so the lattice bleeds edge to edge
const half = Math.hypot(width, height) / 2;
const R0 = u * 0.05 * (0.5 + P.scale * 0.9);
const Rmax = half * (0.62 + P.scale * 0.5);
const spacing = (Rmax - R0) / M;
const waveBase = spacing * (0.3 + P.warp * 1.4);

if (additive) g.blendMode(ADD);

// ---- concentric guilloche rings (the security-print lattice) ----
const rpts = Math.max(90, Math.round(140 + P.density * 140));
for (let k = 0; k < M; k++) {
  const rg = S.ring[k];
  const base = R0 + spacing * k;
  let amp = waveBase * rg.ampMul * (0.72 + 0.42 * Math.sin(drift * rg.dir + k * 0.7));
  amp += A.lowmid * waveBase * 0.35;   // audio on top of the baseline
  amp *= inten;
  const ph = rg.phase0 + drift * rg.dir * (1 + 0.12 * k);
  const kfrac = k / (M - 1 || 1);
  if (style === 'engraved') { g.stroke(wh(hb + rg.hoff * 0.5 + k * 6), 80, 100, 46 * eg); g.strokeWeight(1.15); }
  else if (style === 'currency') { g.stroke(wh(hb + rg.hoff + 60), 74, 96, 60); g.strokeWeight(1.0); }
  else if (style === 'etch') { g.stroke(34, 10, 12, 88); g.strokeWeight(0.95); }
  else if (style === 'blueprint') { g.stroke(wh(200 + rg.hoff * 0.2), 55, 100, 56 + kfrac * 24); g.strokeWeight(1.05); }
  else if (style === 'neon') { g.stroke(wh(hb + k * 22 + prec * 30), 92, 100, 34 * eg); g.strokeWeight(1.25); }
  else { g.stroke(wh(hb + k * 36 + prec * 46), 72, 100, 32 * eg); g.strokeWeight(1.3); }
  g.beginShape();
  for (let i = 0; i <= rpts; i++) {
    const th = (i / rpts) * TAU;
    const r = base + amp * Math.sin(rg.petals * th + ph);
    const a = th + prec;
    g.vertex(cx + r * Math.cos(a), cy + r * Math.sin(a));
  }
  g.endShape();
}

// ---- central rosette (epitrochoid), nested copies — complementary interlace ----
const Rr = u * 0.24 * (0.4 + P.scale * 0.9);
const nCopies = 2 + Math.round(P.density * 2);
const cpts = Math.max(200, Math.round(300 + P.density * 260));
const b0 = S.rc * (1 + 0.16 * Math.sin(K.t * 0.3) + A.bass * 0.3);
for (let c = 0; c < nCopies; c++) {
  const scl = 1 - c * 0.12;
  const phiC = rosPhi + c * 0.5;
  const b = b0;
  if (style === 'engraved') { g.stroke(wh(hb + 172 + c * 26 + rosPhi * 24), 86, 100, 60 * eg); g.strokeWeight(1.4); }
  else if (style === 'currency') { g.stroke(wh(hb + S.hoff2 + 30), 80, 100, 80); g.strokeWeight(1.25); }
  else if (style === 'etch') { g.stroke(30, 12, 8, 92); g.strokeWeight(1.2); }
  else if (style === 'blueprint') { g.stroke(196, 32, 100, 88); g.strokeWeight(1.3); }
  else if (style === 'neon') { g.stroke(wh(hb + 44 + c * 20), 88, 100, 52 * eg); g.strokeWeight(1.4); }
  else { g.stroke(wh(hb + c * 44 + rosPhi * 40), 66, 100, 48 * eg); g.strokeWeight(1.4); }
  g.beginShape();
  for (let i = 0; i <= cpts; i++) {
    const th = (i / cpts) * TAU;
    const x = Rr * scl * (Math.cos(th) + b * Math.cos(S.rm * th + phiC)) / (1 + b);
    const y = Rr * scl * (Math.sin(th) - b * Math.sin(S.rm * th + phiC)) / (1 + b);
    const rx = x * Math.cos(prec) - y * Math.sin(prec);
    const ry = x * Math.sin(prec) + y * Math.cos(prec);
    g.vertex(cx + rx, cy + ry);
  }
  g.endShape();
}

g.blendMode(BLEND);

// ---- center ornament + pulsing rose-engine head ----
if (additive) g.blendMode(ADD);
g.noFill();
g.stroke(wh(hb + 30), (style === 'etch') ? 10 : 60, 100, 74);
g.strokeWeight(1.1);
g.ellipse(cx, cy, u * 0.028); g.ellipse(cx, cy, u * 0.05);
const hd = 3 + K.pulse * 4 + A.treble * 10;
