    if (st!=='op-art' && st!=='woodcut'){
      const cg = Math.max(0, 1-rr*2.2)*(0.10+P.energy*0.16+A.bass*0.3+K.pulse*0.12)*P.glow;
      const gc = pal(0.08+secDrift);
      r+=gc[0]*cg; gg+=gc[1]*cg; b+=gc[2]*cg;
    }
    px[o]=Math.max(0,Math.min(255,r*255));
    px[o+1]=Math.max(0,Math.min(255,gg*255));
    px[o+2]=Math.max(0,Math.min(255,b*255));
    px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();
// audio treble sparkle on the disk (partial, additive, never full-frame; skipped when silent)
if ((A.treble>0.02||A.rms>0.02) && st!=='woodcut' && st!=='op-art'){
  push(); blendMode(ADD); noStroke();
  const gl=(A.treble*0.5+A.rms*0.4)*P.glow;
  fill((P.hue+40)%360, 40, 100, Math.min(24, gl*18));
  const dR=2*Math.min(width,height)*0.47*P.scale;
  circle(CXb/BW*width, CYb/BH*height, dR*0.9);
  blendMode(BLEND); pop();
}

const D = { energy:.6, scale:1, density:.55, speed:1, warp:.7, gamma:2.4, persist:.5, hue:28, x:.5, y:.5, system:'flame', style:'electricsheep', seed:0, act:'breathe', alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// --- coarse accumulation grid (long axis 200; keyed on canvas aspect → survives resize) ---
const LA = 200;
let cw, ch;
if (width >= height){ cw = LA; ch = Math.max(64, Math.round(LA*height/width)); }
else { ch = LA; cw = Math.max(64, Math.round(LA*width/height)); }
if (S.gridKey !== cw+'x'+ch){
  S.gridKey = cw+'x'+ch; S.cw=cw; S.ch=ch;
  S.hist = new Float32Array(cw*ch);
  S.csum = new Float32Array(cw*ch);
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(cw,ch); S.buf.pixelDensity(1);
}
cw=S.cw; ch=S.ch; const N4=cw*ch;

// --- seeded LCG (free-runs; reseed only on P.seed change → seed-deterministic look) ---
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  let z=((P.seed|0)*2654435761 ^ 0x9e3779b9)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.ox=S.rnd()*2-1; S.oy=S.rnd()*2-1; S.oc=S.rnd();
}
const rnd=S.rnd;

// --- build the IFS map set on system/seed change ---
if (S.sysKey !== P.system+'|'+P.seed){
  S.sysKey = P.system+'|'+P.seed;
  const M=[];
  if (P.system==='fern'){
    M.push({p:.01,a:0,b:0,c:0,d:.16,e:0,f:0,v:0,col:.05});
    M.push({p:.85,a:.85,b:.04,c:0,d:-.04,e:.85,f:1.6,v:0,col:.34});
    M.push({p:.07,a:.2,b:-.26,c:0,d:.23,e:.22,f:1.6,v:0,col:.62});
    M.push({p:.07,a:-.15,b:.28,c:0,d:.26,e:.24,f:.44,v:0,col:.9});
    S.dom={x0:-2.8,x1:2.75,y0:0,y1:10};
  } else if (P.system==='sierpinski'){
    const V=[[0,0],[1,0],[.5,.866]];
    for (let i=0;i<3;i++) M.push({p:1/3,a:.5,b:0,c:V[i][0]*.5,d:0,e:.5,f:V[i][1]*.5,v:0,col:i/3+.12});
    S.dom={x0:0,x1:1,y0:0,y1:.866};
  } else if (P.system==='dragon'){
    M.push({p:.5,a:.5,b:-.5,c:0,d:.5,e:.5,f:0,v:0,col:.18});
    M.push({p:.5,a:-.5,b:-.5,c:1,d:.5,e:-.5,f:0,v:0,col:.72});
    S.dom={x0:-.45,x1:1.25,y0:-.45,y1:1.05};
  } else { // 'flame' — curated contractive affines each with a pretty nonlinear variation
    const pretty=[1,3,4,6];               // sinusoidal, swirl, horseshoe, handkerchief (well-behaved, luminous)
    const k=3+(rnd()*2|0);                // 3 or 4 maps
    for (let i=0;i<k;i++){ const s=.42+rnd()*.36;   // contractive rows 0.42..0.78
      M.push({p:1/k, a:(rnd()*2-1)*s, b:(rnd()*2-1)*s, c:(rnd()*2-1)*.92,
                     d:(rnd()*2-1)*s, e:(rnd()*2-1)*s, f:(rnd()*2-1)*.92,
                     v:pretty[(rnd()*pretty.length)|0], col:i/k+rnd()*.12}); }
    S.dom={x0:-1.8,x1:1.8,y0:-1.8,y1:1.8};
