// ---------- draw ----------
if(aMul<1) tint(0,0,100,P.alpha);
image(S.ground,0,0,W,Hh);
noTint();

const nodes=S.nodes, n=nodes?nodes.length:0;
if(n>0){
  const anchorX=clp(P.x,.12,.88)*W, anchorY=clp(P.y,.12,.88)*Hh;
  const sc=clp(P.scale,.4,2.2)*(1+0.03*Math.sin(K.t*0.21));
  const orbX=Math.sin(K.t*0.11)*u*0.035, orbY=Math.cos(K.t*0.083)*u*0.035;
  const rot=K.t*0.028 + Math.sin(K.t*0.05)*0.06;
  const wob=u*0.010*(0.6+0.7*en);
  const wx=new Float32Array(n), wy=new Float32Array(n);
  for(let i=0;i<n;i++){ const p=nodes[i];
    wx[i]=p.x + wob*Math.sin(K.t*0.8 + i*0.37);
    wy[i]=p.y + wob*Math.cos(K.t*0.7 + i*0.31); }
  const wBase=u*0.0016;
  const sapSp=1.6*clp(P.speed,.2,3), sapK=0.16;
  const taperExp=0.30+clp(P.taper,0,1)*0.40;

  push();
  translate(anchorX+orbX, anchorY+orbY);
  rotate(rot);
  scale(sc);
  strokeCap(ROUND);
  noFill();

  if(st==='hyphae'||st==='nerve'){
    const baseHue = st==='nerve'?350:md(P.hue,360);
    // soft wide underlay glow (BLEND, low alpha -> no runaway)
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.6+clp(Math.pow(p.flow,taperExp),1,9));
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      const br=clp(0.45+0.5*sap*(0.5+en)+A.treble*0.5*sap,0,1);
      const hh=md(baseHue+p.depth*0.6+(st==='nerve'?sap*30:sap*14),360);
      stroke(hh, st==='nerve'?70:60, 55*br, 16*aMul);
      strokeWeight(w*2.6);
      line(wx[par],wy[par],wx[i],wy[i]); }
    // bright cores
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.6+clp(Math.pow(p.flow,taperExp),1,9));
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      const br=clp(0.5+0.55*sap*(0.5+en)+A.treble*0.6*sap,0,1.2);
      const hh=md(baseHue+p.depth*0.5,360);
      const sat=st==='nerve'?80:clp(85-p.depth*0.3,42,90);
      stroke(hh, sat, clp(70+40*br,0,100), clp((70+25*sap)*aMul,0,100));
      strokeWeight(w);
      line(wx[par],wy[par],wx[i],wy[i]); }
    // additive swells at branch points / tips (few)
    blendMode(ADD); noStroke();
    let cnt=0;
    for(let i=1;i<n && cnt<90;i++){ const p=nodes[i];
      if((p.ch||0)>=2){ const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
        fill(md(baseHue+(st==='nerve'?10:20),360), st==='nerve'?70:55, 100, clp((8+sap*14)*aMul+A.treble*20*aMul,0,100));
        circle(wx[i],wy[i], wBase*(3+4*sap)); cnt++; } }
    blendMode(BLEND); noFill();
  } else if(st==='leaf'){
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.7+clp(Math.pow(p.flow,taperExp),1,10));
      const dr=clp(p.depth/26,0,1);
      const hh=lrp(38,120,dr);
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      stroke(hh, lrp(72,72,dr), lrp(40,54,dr), clp((78+8*sap)*aMul,0,100));
      strokeWeight(w);
      line(wx[par],wy[par],wx[i],wy[i]); }
  } else if(st==='cyanotype'){
    const lw=Math.max(0.8,u*0.0011);
    strokeWeight(lw);
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      stroke(200,12,100, clp((70+20*sap)*aMul,0,100));
      line(wx[par],wy[par],wx[i],wy[i]); }
    // schematic node ticks at branch points
    stroke(200,20,100,60*aMul); strokeWeight(lw);
    let cnt=0;
    for(let i=1;i<n && cnt<170;i++){ const p=nodes[i];
      if((p.ch||0)>=2){ const t=u*0.006;
        line(wx[i]-t,wy[i],wx[i]+t,wy[i]); line(wx[i],wy[i]-t,wx[i],wy[i]+t); cnt++; } }
  } else { // ink-root sumi
    for(let i=1;i<n;i++){ const p=nodes[i], par=p.par; if(par<0)continue;
      const w=wBase*(0.7+clp(Math.pow(p.flow,taperExp+0.1),1,12));
      const jit=1+0.18*Math.sin(K.t*0.9+i*1.7);
      const sap=0.5+0.5*Math.sin(K.t*sapSp - p.depth*sapK);
      stroke(28,22, lrp(24,12, clp(p.flow/40,0,1)), clp((80+10*sap)*aMul,0,100));
      strokeWeight(w*jit);
      line(wx[par],wy[par],wx[i],wy[i]); }
  }
  pop();
}
drawingContext.shadowBlur=0;
blendMode(BLEND);

const D = { density:.5, warp:.25, energy:.6, speed:1, scale:1, hue:210, x:.5, y:.5, style:'stained', pal:'spectrum', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style, pal=P.pal;
const dens=clp(P.density,0,1), warp=clp(P.warp,0,1), en=clp(P.energy,0,1)*(.45+.7*K.intensity);
const NS=Math.max(4,Math.round(6+dens*54));                 // 6..60 sites
const gN=Math.max(14,Math.round(16+ (1-clp(P.scale,0.4,2.2)/2.2)*22 )); // coarseness by scale (bigger scale -> chunkier)

// ---- seed-deterministic site field (normalized coords) ----
if(S.seedUsed!==P.seed || !S.sx || S.nUsed!==NS){
  S.seedUsed=P.seed; S.nUsed=NS;
  S.sx=[]; S.sy=[]; S.vx=[]; S.vy=[]; S.sh=[]; S.sk=[];
  for(let i=0;i<NS;i++){
    S.sx[i]=fr(i*1.3+3.1); S.sy[i]=fr(i*2.7+7.7);
    const ang=fr(i*5.1)*TAU, sp=0.02+0.05*fr(i*9.2);
    S.vx[i]=Math.cos(ang)*sp; S.vy[i]=Math.sin(ang)*sp;
    S.sh[i]=fr(i*3.9); S.sk[i]=fr(i*11.3);               // hue jitter, warp phase
  }
  S.lastT=null;
}
// integrate drift by real seconds (never re-phases; tolerate t0 reset)
if(S.lastT==null || K.t<S.lastT) S.lastT=K.t;
let dt=clp(K.t-S.lastT,0,0.05); S.lastT=K.t;
const rate=(0.25+0.9*en)*clp(P.speed,0.2,4);
// act dramaturgy: drift=free, swarm=gather-then-scatter each section, breathe=in/out pulse
let radial=(K.pulse*0.12+A.bass*0.20)*en;                 // +out on the beat
if(P.act==='swarm'){ radial += (K.section%2? 0.09 : -0.09)*en; }        // alternate gather/scatter
else if(P.act==='breathe'){ radial += Math.sin(K.t*0.12)*0.10*en; }     // slow inhale/exhale
for(let i=0;i<NS;i++){
  S.sx[i]+=S.vx[i]*dt*rate + (S.sx[i]-P.x)*radial*dt*3;
  S.sy[i]+=S.vy[i]*dt*rate + (S.sy[i]-P.y)*radial*dt*3;
  if(S.sx[i]<0.02){S.sx[i]=0.02;S.vx[i]=Math.abs(S.vx[i]);} else if(S.sx[i]>0.98){S.sx[i]=0.98;S.vx[i]=-Math.abs(S.vx[i]);}
  if(S.sy[i]<0.02){S.sy[i]=0.02;S.vy[i]=Math.abs(S.vy[i]);} else if(S.sy[i]>0.98){S.sy[i]=0.98;S.vy[i]=-Math.abs(S.vy[i]);}
}
// warp wander of boundaries (per-site slow offset, real-time)
const wa=warp*0.06;
const px=[],py=[];
for(let i=0;i<NS;i++){
  px[i]=(S.sx[i]+wa*Math.sin(K.t*(0.3+S.sk[i]*0.6)+S.sk[i]*TAU))*W;
  py[i]=(S.sy[i]+wa*Math.cos(K.t*(0.25+S.sh[i]*0.5)+S.sh[i]*TAU))*Hh;
}

// ---- palette ----
function cellHue(i){
  const base=md(P.hue + (pal==='spectrum'? S.sh[i]*300 : pal==='duo'? (i%2)*160 : pal==='warm'? S.sh[i]*70 : pal==='cool'? 140+S.sh[i]*120 : S.sh[i]*40),360);
  return base;
}
const dark = style==='contour'||style==='thermal'||pal==='mono';
// background base
if(style==='contour'){ background(md(P.hue+200,360),40,7); }
else if(style==='thermal'){ background(255,60,4); }
else if(pal==='mono'){ background(md(P.hue,360),8,10); }
else { background(md(P.hue+180,360),20,8); }

const cw=W/gN, ch=Hh/gN;
noStroke();
// section drives global saturation/brightness breathing
const secB=0.85+0.3*Math.sin(K.t*0.05+K.section);
const glow=(0.3+0.7*en)*(0.6+0.6*K.swell+0.8*A.treble);

for(let gx=0;gx<gN;gx++){
  const cx=gx*cw+cw*0.5;
  for(let gy=0;gy<gN;gy++){
    const cy=gy*ch+ch*0.5;
    let best=1e18,b2=1e18,bi=0;
    for(let k=0;k<NS;k++){
      const dx=px[k]-cx, dy=py[k]-cy, d=dx*dx+dy*dy;
      if(d<best){b2=best;best=d;bi=k;} else if(d<b2){b2=d;}
    }
    const edge=clp((Math.sqrt(b2)-Math.sqrt(best))/(u*0.10),0,1); // 0 near boundary, 1 deep interior
    const h=cellHue(bi);
    if(style==='contour'){
      if(edge<0.14){ const g2=clp((0.14-edge)/0.14,0,1); fill(h,55,25+70*g2*(0.5+glow*0.5),100); rect(gx*cw,gy*ch,cw+1,ch+1); }
      continue;
    }
    if(style==='thermal'){
      // false-color heat ramp from interior(hot) to edge(cold)
      const v=clp(best/(u*u*0.10),0,1);           // normalized dist to site
      const hv=md(20 - v*230 + P.hue-210,360);    // red->blue ramp
      const b=clp(90-v*55+ (1-edge)*20*glow,10,100);
      fill(hv, 80, b, 100); rect(gx*cw,gy*ch,cw+1,ch+1); continue;
    }
    if(style==='shard'){
      const b=clp((26+58*edge)*secB,8,96);
      fill(h,70, b,100); rect(gx*cw,gy*ch,cw+1,ch+1);
      if(edge<0.05){ fill(0,0,4,100); rect(gx*cw,gy*ch,cw+1,ch+1); }  // thin hard facet break
      continue;
    }
    if(style==='membrane'){
      // organic: bright rim near boundary, translucent nucleus dark center
      const b=clp((24+50*(1-edge))*secB,8,92);
      const s2=clp(38+40*edge,20,90);
      fill(h,s2,b,100); rect(gx*cw,gy*ch,cw+1,ch+1);
      if(edge<0.10){ fill(md(h+20,360),30,96,60*glow); rect(gx*cw,gy*ch,cw+1,ch+1); }
      continue;
    }
    // stained (default): luminous glass fill + dark leading at boundaries
    const b=clp((34+52*edge)*secB,10,96);
    fill(h,62, b,100); rect(gx*cw,gy*ch,cw+1,ch+1);
    if(edge<0.06){ fill(md(P.hue+200,360),50,4,100); rect(gx*cw,gy*ch,cw+1,ch+1); } // leading
    else if(edge<0.16){ fill(h,20,96,45*glow); rect(gx*cw,gy*ch,cw+1,ch+1); }        // rim highlight
  }
}

// audio/beat sparkle at site nuclei (real-time-independent accent on top)
if(style!=='contour'){
  noStroke();
  for(let i=0;i<NS;i++){
    const r=u*0.008*(1+2*K.pulse+3*A.treble)*clp(P.scale,0.4,2.2);
    fill(md(cellHue(i)+40,360),20,100, 40+50*glow);
    circle(px[i],py[i], r);
  }
}
blendMode(BLEND); drawingContext.shadowBlur=0; noStroke();

const D = { density:.5, relief:.55, energy:.6, scale:1, hue:282, speed:1, x:.5, y:.5, style:'gem', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), frc=v=>v-Math.floor(v), TAU=Math.PI*2;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H);
const style=P.style, wire=style==='wireframe', stained=style==='stained', lowp=style==='lowpoly';
const dens=clp(P.density,0,1), relief=clp(P.relief,0,1), en=clp(P.energy,0,1);
const nCells=Math.round(14+dens*58);

// ---- reseed per section: geometry key folds section into the effective seed ----
const sec = Math.floor(K.section)||0;
const effSeed = (P.seed|0) + sec*101;
const gkey = W+'x'+H+':'+nCells+':'+effSeed;
if(S.gkey!==gkey){
  S.gkey=gkey;
  const hsh=i=>{const s=Math.sin(i*127.1+effSeed*311.7)*43758.5453;return s-Math.floor(s);};
  const cols=Math.max(2,Math.round(Math.sqrt(nCells*W/H))), rows=Math.max(2,Math.ceil(nCells/cols));
  const sites=[]; let idx=0;
  for(let r=0;r<rows && idx<nCells;r++)for(let c=0;c<cols && idx<nCells;c++){
    const jx=(hsh(idx*2+1)-.5)*0.92, jy=(hsh(idx*2+2)-.5)*0.92;
    sites.push([(c+0.5+jx)/cols*W,(r+0.5+jy)/rows*H,hsh(idx*3+7)]); idx++;
  }
  const cells=[];
  for(let i=0;i<sites.length;i++){
    let poly=[[0,0],[W,0],[W,H],[0,H]];
    const px=sites[i][0], py=sites[i][1];
    for(let j=0;j<sites.length && poly.length;j++){
      if(j===i)continue;
      const qx=sites[j][0], qy=sites[j][1];
      const mx=(px+qx)/2, my=(py+qy)/2, nx=px-qx, ny=py-qy;
      const out=[];
      for(let k=0;k<poly.length;k++){
        const Aa=poly[k], Bb=poly[(k+1)%poly.length];
        const dA=(Aa[0]-mx)*nx+(Aa[1]-my)*ny;
        const dB=(Bb[0]-mx)*nx+(Bb[1]-my)*ny;
        if(dA>=0) out.push(Aa);
        if((dA>=0)!==(dB>=0)){ const t=dA/(dA-dB); out.push([Aa[0]+t*(Bb[0]-Aa[0]),Aa[1]+t*(Bb[1]-Aa[1])]); }
      }
      poly=out;
    }
    if(poly.length>=3){
      let cx=0,cy=0; for(const v of poly){cx+=v[0];cy+=v[1];} cx/=poly.length; cy/=poly.length;
      cells.push({v:poly,cx,cy,ph:sites[i][2],hj:sites[i][2]-0.5});
    }
  }
  S.cells=cells;
}
const cells=S.cells||[];

// ---- drifting light (real-time motion floor, never rephases) ----
let actLmul=1, actH=1, actJit=0;
if(P.act==='shatter'){ actLmul=1.9; actH=1.35; actJit=0.5; }
else if(P.act==='grow'){ actH=0.45+0.9*frc(K.section/8+K.t*0.01); }
const laz=K.t*0.17*(0.5+P.speed*0.7)*actLmul + (P.x-0.5)*3.0;
const lel=0.55+0.28*Math.sin(K.t*0.083)+(P.y-0.5)*0.5;
let Lx=Math.cos(laz)*Math.cos(lel), Ly=Math.sin(laz)*Math.cos(lel), Lz=Math.sin(lel)+0.35;
{ const ll=Math.hypot(Lx,Ly,Lz)||1; Lx/=ll; Ly/=ll; Lz/=ll; }
const hBase=u*(0.035+relief*0.24)*actH;
const intens=0.65+0.55*K.intensity;

// ---- background ----
const bgH=((P.hue%360)+360)%360;
if(wire){ background(bgH,55,6); }
else if(stained){ background(bgH,30,4); }
else { background(bgH,lowp?18:44,lowp?12:7); }

noStroke();
for(let ci=0;ci<cells.length;ci++){
  const cell=cells[ci], v=cell.v, n=v.length, cx=cell.cx, cy=cell.cy;
  // per-cell beat breathe (staggered so field never re-aligns as one flash)
  const cph=frc(K.beat*0.5*P.speed+cell.ph);
  const pop=Math.pow(1-cph,2.3);
  const jit=actJit? (frc(cell.ph*13.7+K.beat*0.25)-0.5)*u*0.02*actJit*en : 0;
  const h=hBase*(0.45+0.75*pop+A.bass*1.15)*intens;
  const cellH=(bgH+cell.hj*46+K.t*4)%360;

  if(stained){
    // flat translucent jewel cell, thick dark leading, backlit — mass + lead, no facets
    const lit=clp(0.42+0.5*Math.sin(cell.ph*TAU+laz)+0.4*K.swell+A.bass*0.5,0.12,1);
    fill((cellH+360)%360, 58+22*en, 30+58*lit, 92);
    beginShape(); for(let k=0;k<n;k++) vertex(v[k][0],v[k][1]); endShape(CLOSE);
    continue;
  }

  // faceted pyramid: apex above centroid, fan of lit triangles
  for(let k=0;k<n;k++){
    const a=v[k], b=v[(k+1)%n];
    const e1x=a[0]-cx, e1y=a[1]-cy, e1z=-h;
    const e2x=b[0]-cx, e2y=b[1]-cy, e2z=-h;
    let nx=e1y*e2z-e1z*e2y, ny=e1z*e2x-e1x*e2z, nz=e1x*e2y-e1y*e2x;
    if(nz<0){ nx=-nx; ny=-ny; nz=-nz; }
    const nl=Math.hypot(nx,ny,nz)||1;
    const diff=(nx*Lx+ny*Ly+nz*Lz)/nl;
    const lit=clp(0.5+0.5*diff,0,1);
    if(wire){
      const g=clp(0.15+0.85*lit,0,1);
      stroke((cellH+360)%360, 70-40*g, 40+60*g, 30+65*g);
      strokeWeight(1+1.4*g*en);
      line(cx+jit,cy+jit,a[0]+jit,a[1]+jit);
    } else {
      const spec=lowp?0:Math.pow(clp(diff,0,1),22)*95*en;
      const sat=(lowp?24+18*en:62+30*en)*(1-Math.min(0.85,spec/110));
      const bri=(lowp?34+50*lit:16+72*lit)+spec;
      fill((cellH+360)%360, clp(sat,0,100), clp(bri,0,100));
      triangle(cx+jit,cy+jit,a[0]+jit,a[1]+jit,b[0]+jit,b[1]+jit);
    }
  }
  // cut-gem facet edges / stained leading handled below per style
  if(!wire && !lowp){
    noFill(); stroke(bgH,40,4,55); strokeWeight(u*0.0016);
    beginShape(); for(let k=0;k<n;k++) vertex(v[k][0],v[k][1]); endShape(CLOSE);
    noStroke();
  }
}

// stained: heavy leading pass over the whole partition
if(stained){
  noFill(); stroke(bgH,45,2,96); strokeWeight(u*0.006*(0.8+0.4*K.swell));
  for(const cell of cells){ const v=cell.v; beginShape(); for(let k=0;k<v.length;k++) vertex(v[k][0],v[k][1]); endShape(CLOSE); }
  // soft backlight bloom on the beat
  blendMode(ADD); noStroke();
  const gl=18+30*K.pulse+A.bass*40;
  fill(((bgH+40)%360),50,90,clp(gl*0.12,0,26));
  rect(0,0,W,H);
  blendMode(BLEND);
}

// specular sparkle on strongest-lit apexes (gem only) — tiny, adds live shimmer
if(!wire && !stained && !lowp && en>0.15){
  blendMode(ADD); noStroke();
  const spark=clp(K.pulse*0.8+A.treble*1.2,0,1);
  if(spark>0.05){
    for(let ci=0;ci<cells.length;ci+=3){
      const cell=cells[ci];
      const sz=u*0.012*(0.5+spark);
      fill(50,10,100,clp(40*spark,0,55));
      circle(cell.cx,cell.cy,sz);
    }
  }
  blendMode(BLEND);
