  if (H < 60) { r = c; g = xx; b = 0; } else if (H < 120) { r = xx; g = c; b = 0; }
  else if (H < 180) { r = 0; g = c; b = xx; } else if (H < 240) { r = 0; g = xx; b = c; }
  else if (H < 300) { r = xx; g = 0; b = c; } else { r = c; g = 0; b = xx; }
  return [(r + m) * 255, (g + m) * 255, (b + m) * 255];
}
const sty = P.style;
let bd, wr, gw;
if (sty === 'copper-pcb') { bd = [138, 62, 18]; wr = [26, 80, 62]; gw = [40, 45, 100]; }
else if (sty === 'phosphor') { bd = [132, 78, 10]; wr = [128, 88, 50]; gw = [120, 22, 100]; }
else if (sty === 'neon-tube') { bd = [252, 66, 17]; wr = [222, 88, 64]; gw = [305, 55, 100]; }
else if (sty === 'gold-leadframe') { bd = [238, 45, 11]; wr = [44, 86, 60]; gw = [48, 22, 100]; }
else { bd = [196, 66, 16]; wr = [187, 86, 64]; gw = [185, 22, 100]; } // circuit-cyan
