const hoff = (P.hue - 190) + K.section * 7 + Math.sin(K.t * 0.045) * 6;
const boardC = hsb2rgb(bd[0] + hoff * 0.4, bd[1], bd[2]);
const wireC = hsb2rgb(wr[0] + hoff, wr[1], wr[2]);
const glowC = hsb2rgb(gw[0] + hoff, gw[1], gw[2]);

const expo = (0.5 + P.energy * 0.85 + K.intensity * 0.32 + K.swell * 0.12 + A.rms * 0.5 + A.treble * 0.35);
const wireBoost = 0.85 + K.swell * 0.15 + A.lowmid * 0.25;

