const cx = P.x, cy = P.y;
const b0r = boardC[0], b0g = boardC[1], b0b = boardC[2];
const wRr = wireC[0] * wireBoost, wGg = wireC[1] * wireBoost, wBb = wireC[2] * wireBoost;
const gRr = glowC[0], gGg = glowC[1], gBb = glowC[2];
for (let y = 0; y < CH; y++) {
  const fy = y / CH - cy;
  for (let x = 0; x < CW; x++) {
    const i = y * CW + x, s = cur[i], o = i * 4;
    const fx = x / CW - cx;
    let r, gg, b;
    if (s === 0) {
